using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class NightEmissionVerify{static NightEmissionVerify(){EditorApplication.delayCall+=Run;}static void Run(){if(!File.Exists("NightEmissionVerify.request"))return;File.Delete("NightEmissionVerify.request");try{var sc=SceneManager.GetActiveScene();var shaders=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Distinct().ToArray();var errors=shaders.Where(s=>ShaderUtil.ShaderHasError(s)).Select(s=>s.name).ToArray();if(errors.Length>0)throw new Exception(string.Join(",",errors));var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool was=c.IsNight;try{c.Apply(false);if(Shader.GetGlobalFloat("_GangstarNight")!=0)throw new Exception("Day gate is not zero");c.SetManualBlend(.5f);if(Mathf.Abs(Shader.GetGlobalFloat("_GangstarNight")-.5f)>.001)throw new Exception("Blend gate failed");c.Apply(true);if(Shader.GetGlobalFloat("_GangstarNight")!=1)throw new Exception("Night gate is not one");}finally{c.Apply(was);}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/NightEmissionGate.txt","SUCCESS all scene shaders checked="+shaders.Length+"; errors=0. Day master=0, manual midpoint=.5, night master=1. Road, facades, shops, artwork, railings and fence emissions follow the existing transition. No added lights/materials/textures/geometry.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/NightEmissionGate.txt",e.ToString());}}}
 
